    private static void ConfigureInputPanel(RoundedPanel panel, Label icon, TextBox textBox, string iconText, string placeholder)
    {
        panel.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        panel.BorderColor = Color.FromArgb(203, 213, 225);
        panel.BorderRadius = 5;
        panel.Controls.Add(icon);
        panel.Controls.Add(textBox);
        panel.FillColor = Color.White;
        panel.Margin = new Padding(0, 0, 12, 8);
        panel.Size = new Size(160, 30);
        icon.BackColor = Color.Transparent;
        icon.Font = new Font("Segoe MDL2 Assets", 12F);
        icon.ForeColor = Color.FromArgb(71, 85, 105);
        icon.Location = new Point(8, 5);
        icon.Size = new Size(22, 20);
        icon.Text = iconText;
        icon.TextAlign = ContentAlignment.MiddleCenter;
        textBox.BorderStyle = BorderStyle.None;
        textBox.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        textBox.Font = new Font("Segoe UI", 9F);
        textBox.ForeColor = Color.FromArgb(30, 41, 59);
        textBox.Location = new Point(38, 6);
        textBox.PlaceholderText = placeholder;
        textBox.Size = new Size(110, 16);
    }

