    private static void ConfigureActionButton(Button button, string text, Color backColor, Color foreColor, Point location, Size size)
    {
        button.BackColor = backColor;
        button.FlatAppearance.BorderColor = backColor == Color.White ? Color.FromArgb(203, 213, 225) : backColor;
        button.FlatStyle = FlatStyle.Flat;
        button.Font = new Font("Segoe UI", 8.5F, FontStyle.Bold);
        button.ForeColor = foreColor;
        button.Location = location;
        button.Size = size;
        button.Text = text;
        button.UseVisualStyleBackColor = false;
    }

