    private static void ConfigureFooterCell(Panel cell, Label icon, Label text, Panel divider, string iconText, string value)
    {
        cell.BackColor = Color.Transparent;
        cell.Controls.Add(icon);
        cell.Controls.Add(text);
        if (divider != null)
        {
            cell.Controls.Add(divider);
            divider.BackColor = Color.FromArgb(226, 232, 240);
            divider.Dock = DockStyle.Right;
            divider.Width = 1;
        }

        icon.Font = new Font("Segoe MDL2 Assets", 10F);
        icon.ForeColor = Color.FromArgb(100, 116, 139);
        icon.Location = new Point(18, 9);
        icon.Size = new Size(22, 20);
        icon.Text = iconText;
        icon.TextAlign = ContentAlignment.MiddleCenter;
        text.Font = new Font("Segoe UI", 8F);
        text.ForeColor = Color.FromArgb(71, 85, 105);
        text.Location = new Point(44, 9);
        text.Size = new Size(260, 20);
        text.Text = value;
        text.TextAlign = ContentAlignment.MiddleLeft;
